@ValidatorConstraint({ name: 'TiersValidator', async: false })
@Injectable()
export class TiersValidatorRule implements ValidatorConstraintInterface {
    validate(tiers: Tier[], args: ValidationArguments) {
        if (!tiers || tiers.length === 0) {
            return true;
        }

        const dto = args.object as CreateDimensionDto;
        const { usageEntitlement, overageAllowed, consumptionPrice, usageIncrement } = dto;

        // Tiered dimensions are mutually exclusive with usageEntitlement, consumptionPrice, and overageAllowed: true
        if (usageEntitlement !== undefined && usageEntitlement !== null) {
            return false;
        }
        if (consumptionPrice !== undefined && consumptionPrice !== null) {
            return false;
        }
        if (overageAllowed === overageAllowedEnum.true) {
            return false;
        }

        // Sort tiers by tierPosition
        const sortedTiers = [...tiers].sort((a, b) => parseInt(a.tierPosition) - parseInt(b.tierPosition));

        // Check that tier positions are sequential starting from 1
        for (let i = 0; i < sortedTiers.length; i++) {
            if (parseInt(sortedTiers[i].tierPosition) !== i + 1) {
                return false;
            }
        }

        // Check bounds
        let previousUpperBound: number | null = null;
        for (let i = 0; i < sortedTiers.length; i++) {
            const tier = sortedTiers[i];
            const upperBound = tier.upperBound;

            // Check upperBound format
            if (upperBound !== 'inf' && isNaN(parseFloat(upperBound))) {
                return false;
            }

            // "inf" only allowed at the end
            if (upperBound === 'inf' && i !== sortedTiers.length - 1) {
                return false;
            }

            // Bounds must increase without overlap
            if (previousUpperBound !== null) {
                if (upperBound === 'inf') {
                    // inf is always greater than any number
                    continue;
                }
                const currentUpperBound = parseFloat(upperBound);
                if (currentUpperBound <= previousUpperBound) {
                    return false;
                }
            }

            if (upperBound !== 'inf') {
                previousUpperBound = parseFloat(upperBound);
            }

            // Bounds must align to usageIncrement
            if (upperBound !== 'inf' && usageIncrement) {
                const increment = parseInt(usageIncrement);
                const bound = parseFloat(upperBound);
                if (bound % increment !== 0) {
                    return false;
                }
            }

            // Every tier after the first requires unitPrice
            if (i > 0 && (!tier.unitPrice || tier.unitPrice === '')) {
                return false;
            }

            // First tier can have optional unitPrice (free tier if omitted)
            if (i === 0 && tier.unitPrice && isNaN(parseFloat(tier.unitPrice))) {
                return false;
            }

            // Validate unitPrice format for all tiers that have it
            if (tier.unitPrice && isNaN(parseFloat(tier.unitPrice))) {
                return false;
            }
        }

        return true;
    }

    defaultMessage(args: ValidationArguments) {
        return 'Invalid tiers configuration. Tiers are mutually exclusive with usageEntitlement, consumptionPrice, and overageAllowed. Bounds must increase without overlap, align to usageIncrement, and "inf" only at the end. Every tier after the first requires unitPrice.';
    }
}

export function TiersValidator(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'TiersValidator',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TiersValidatorRule,
        });
    };
}

